INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163965-gs355', 'stk-abu_abdullah', 'GS 355', 'info', '{"desc": "ههههههههههههههههههههههههههههههههههههههههه\nالمادة خسسسسسسسسسسسف وشغل كثيييير وبروجكت وسلايدات محشوه بالهرج الفاضي وزياده كمان يعطيك أوراق خارجية وبحوث أحيانا توصل 10 صفحات من الكلام الفاضي …\n\nصوره من السلايدات 🙂\n\nhttp://img46.imageshack.us/img46/2829/20130114113342.png\n\nللي يبي السلايدات كاملة راح أرفعها لكم بس يرسل لي رسالة خاصة !!\nوإذا كنت تبي تاخذ A+ أو A أو B+ مستحييييييل … أنحش من ذا الكورس …\nكان هالترم عندنا ميجر 1 … وبروجكت غثيييييث و فاينل !!\n\nطبعاً محد جاب فل مارك بالميجر ون … وأعلى واحد تقريباً 18 بس لغته ممتازة جداً … أما الفاينل حدث ولا حرج … أعلى واحد تقريباً 35 أو 30 من 40 !! طبعاً هذي طارت منك قريدين ولا ثلاثة لأنه ستاندرد …\n\nفي بداية الترم كان عدد الطلاب ماشي الحال وكانوا ثلاث سكاشن …\nفي نهاية الترم ولما أختبرنا الفاينل مستعد أحلف لكم أن عدد الطلاب مايتجاوز أصابع اليد أو أكثر شوي والباقيين كلهم حذفوا …\n\nطبعاً أنا جبت C+ مع أني حفظت السلايدات حفظ وراجعتها أكثر من مره ولكنها طويلة جداً وإنصدمت جداً بالقريد وأتوقع فيه شباب غيري جابوا D+ أو D !!!\n\nتخيل معي 14 أسبوع … كل أسبوع فيه كلاسين … وكل كلاس له سلايدات تقريباً 14 أو 15 سلايد محشي بالكلام مثل اللي فوق … عاد أحسبها وشف كم يطلع لك سلايد 😞\n\nأكرر … اللي يبي قريد هالكورس مايصلح له أبد أبد أبد !!\nالهدف من كورسات الجي اس هو رفع المعدل وليس الخسف … طبعاً ما أستفدت شيء أبداً !!!\nأنحش ولاتقول مادريت لأني حذرتكم …\nوالسعيد من يتعظ بغيره 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-355-cultural-anthropology/120485/8", "user": "Abu_Abdullah", "ts": 1358153050000, "tid": 120485, "pn": 8}}', 1358153050000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437724-gs355', 'stk-medoalkebsi', 'GS 355', 'info', '{"desc": "انا اخذت عند SIMEON MAGLIVERAS\n\nCourse Description:\nThis course introduces the discipline of cultural anthropology, including key theoretical and methodological approaches to the study of culture. The nature of ethnographic analysis: how cultural anthropologists understand, describe, explain, and highlight the particularities, similarities, and differences of the human experience. Examine the comparative study of contemporary human societies, cultures, and diversity, including local and regional cultures. How people adapt to, make sense of, and transform their worlds. Examine and understand the cultural dimensions of human life expressed through value of systems, language, and social practices and their meanings.\n\nالكورس سهالات يعني مو زي لما كان مع تيم. كورس حليوه لانه اغلبه سواليف مع الدكتور عن الحضارات واشياء زي كذا .\nسهل تجيب فيه قريد . طبعا عندكم القرطبي افضل من ناحيه القريدات . كلهم يدفون بس القرطبي يطيرك ههه.\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-355-cultural-anthropology/120485/22", "user": "Medoalkebsi", "ts": 1451720600000, "tid": 120485, "pn": 22}}', 1451720600000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1445320-gs355', 'stk-way_to_aim', 'GS 355', 'info', '{"desc": "simeon magliveras\nما في كتاب للمادة\nالمحاضرة: سوالف و فيديو (بالنسبة لي شيء ممل و غير مفيد)\nما في كويزات و لا هموركات\nفي بروجكت في نهاية الفصل\nالاختبارات: باعتبار ما في كتاب و السيلبوس مو واضح في شيء يزيد و اخر يحذف\nيمكن ما تعرف عن مادة الاختبار إلا قبل الاختبار بأسبوع أو أكثر بقليل\nو الاختبار عنده يعتمد على الفهم و الحفظ ( مب قليل )\n\nالي ما تعود يقرأ شبتر كامل و مقالات طويلة بالانجلزي أو ما له ميول له بضيع في الكورس\nهذا الكورس مب سهل لانه ليس ملموس في الحياة العامة\nليس مثل كورسات العربي و الاسلامي و international relation", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-355-cultural-anthropology/120485/23", "user": "way_to_aim", "ts": 1459327127000, "tid": 120485, "pn": 23}}', 1459327127000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1447749-gs355', 'stk-user8914', 'GS 355', 'info', '{"desc": "Simeon Magliveras\n\nخذ عنده وماراح تندم ابدا\n12 درجة بونص وباقي الفاينل ممكن يكون فيه بونص !\nطريقته في المياجر يكون فيه اسئلة زياده \" بونص\" غير ال20 سؤال 3 درجات بونص لكل ميجر\nو 6 درجات بونص اذا حضرت سمينار 3 مرات كل واحد درجتين بونص\nمافيه واجبات ولا كويزات ولا خرابيط ماتعرف الماده إلا قبل يوم الميجر فقط\nهي عليها درجات في السيلبس لكنه ساحب عليها\nالبرزنتيشن يتكي مع الطلاب ومابيده ورقه يسجل فيها ملاحظات ولا شي عندي احساس ان كل الطلاب فل مارك في البرزنتيشن\nالكلاس عن نفسي اشوفه ممتع لأنه مهو شرح قد ماهو نقاش واخذ وعطى وسواليف\n\nاذا حصلكم لاتفوتونه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-355-cultural-anthropology/120485/25", "user": "user8914", "ts": 1461965641000, "tid": 120485, "pn": 25}}', 1461965641000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
